from datetime import datetime, timezone
import csv
import io
import math


def haversine_km(lat1, lon1, lat2, lon2):
    if not all(math.isfinite(v) for v in (lat1, lon1, lat2, lon2)):
        raise ValueError("All coordinates must be finite numbers")
    if not (-90 <= lat1 <= 90):
        raise ValueError(f"Latitude 1 must be in [-90, 90], got {lat1}")
    if not (-90 <= lat2 <= 90):
        raise ValueError(f"Latitude 2 must be in [-90, 90], got {lat2}")
    if not (-180 <= lon1 <= 180):
        raise ValueError(f"Longitude 1 must be in [-180, 180], got {lon1}")
    if not (-180 <= lon2 <= 180):
        raise ValueError(f"Longitude 2 must be in [-180, 180], got {lon2}")
    radius = 6371.0088
    lat1_rad, lon1_rad = math.radians(lat1), math.radians(lon1)
    lat2_rad, lon2_rad = math.radians(lat2), math.radians(lon2)
    dlat, dlon = lat2_rad - lat1_rad, lon2_rad - lon1_rad
    a = math.sin(dlat / 2) ** 2 + math.cos(lat1_rad) * math.cos(lat2_rad) * math.sin(dlon / 2) ** 2
    a = max(0.0, min(1.0, a))
    return float(radius * 2 * math.asin(math.sqrt(a)))


def observation_age_minutes(timestamp: str, now: datetime) -> float:
    if now.tzinfo is None:
        raise ValueError("now must be timezone-aware")
    ts_str = timestamp
    if ts_str.endswith("Z"):
        ts_str = ts_str[:-1] + "+00:00"
    try:
        obs_time = datetime.fromisoformat(ts_str)
    except (ValueError, TypeError) as error:
        raise ValueError(f"Invalid timestamp: {timestamp}") from error
    if obs_time.tzinfo is None:
        obs_time = obs_time.replace(tzinfo=timezone.utc)
    delta = now.astimezone(timezone.utc) - obs_time.astimezone(timezone.utc)
    return max(0.0, delta.total_seconds() / 60.0)


def parse_firms_csv(text):
    records, skipped = [], 0
    reader = csv.DictReader(io.StringIO(text))
    required_headers = {"latitude", "longitude", "acq_date", "acq_time"}
    if not required_headers.issubset(set(reader.fieldnames or [])):
        raise ValueError("Missing required headers")
    for row in reader:
        try:
            lat, lon = float(row["latitude"]), float(row["longitude"])
            if not (math.isfinite(lat) and math.isfinite(lon)):
                raise ValueError("Nonfinite coordinates")
            if not (-90 <= lat <= 90) or not (-180 <= lon <= 180):
                raise ValueError("Coordinates out of range")
            date_str, time_str = row["acq_date"], row["acq_time"]
            if not date_str or not time_str:
                raise ValueError("Missing acquisition time")
            dt = datetime.strptime(date_str + time_str.zfill(4), "%Y-%m-%d%H%M")
            observed_at = dt.replace(tzinfo=timezone.utc).isoformat()
            records.append({
                "lat": lat, "lon": lon, "observed_at": observed_at,
                "confidence": row.get("confidence") or "unknown",
            })
        except (ValueError, TypeError, KeyError):
            skipped += 1
    return records, skipped
